(function (all) { var mine = all["vi"] = all["vi"] || {}; var add = {"manual.831d0f72d242":"Bắt đầu","manual.f2f53974b760":"Freally Capture là một studio trên máy tính dành cho Windows, macOS và Linux. Hướng dẫn này mô tả phiên bản 1.2.1, bản phát hành hiện tại.","manual.4b5f10daa08b":"Mở Freally Capture. Ở lần đầu tiên, ứng dụng yêu cầu bạn chấp nhận thỏa thuận cấp phép; sau đó một trình hướng dẫn thiết lập kiểm tra card đồ họa và bộ xử lý của bạn, rồi đề xuất bộ mã hóa, kích thước khung vẽ và bitrate, kèm lý do cho từng lựa chọn.","manual.fe88634050bf":"Studio mở ra với bản xem trước chương trình cùng các dock <strong>Cảnh</strong>, <strong>Nguồn</strong>, <strong>Bàn trộn</strong> và <strong>Điều khiển</strong>. Không có tài khoản và không cần đăng nhập.","manual.4c937d2528ca":"Trên <strong>macOS</strong>, hãy cho phép <strong>Ghi màn hình</strong> — cùng <strong>Camera</strong> và <strong>Micrô</strong> nếu bạn dùng chúng — trong Cài đặt hệ thống → Quyền riêng tư &amp; Bảo mật, rồi mở lại ứng dụng. Trên <strong>Linux với Wayland</strong>, hộp thoại của chính môi trường máy tính sẽ hỏi bạn muốn chia sẻ màn hình hay cửa sổ nào.","manual.adc8f305f8f8":"Thêm nguồn đầu tiên của bạn (xem <a href=\"#build-a-scene\">Dựng một cảnh</a>) là bạn đã sẵn sàng ghi hình hoặc phát trực tiếp.","manual.46e49bd74b1d":"Dựng một cảnh","manual.f779d891c1f2":"Một cảnh là một chồng nguồn được ghép trên card đồ họa. Một nguồn có thể được nhiều cảnh dùng chung.","manual.5a1c5f778fdb":"Trong dock <strong>Nguồn</strong>, nhấp <strong>Thêm nguồn</strong> và chọn một loại: <strong>Màn hình</strong>, <strong>Cửa sổ</strong>, <strong>Trò chơi</strong>, <strong>Webcam / Card ghi hình</strong>, <strong>Trình duyệt</strong>, <strong>Media</strong>, <strong>Ảnh</strong>, <strong>Văn bản</strong>, <strong>Màu</strong> hoặc <strong>Âm thanh</strong>.","manual.2a2d9e2015b5":"Thêm một nguồn <strong>Chụp Màn hình</strong>: bản xem trước chương trình sẽ hiện đầy màn hình của bạn.","manual.80c8e9c8176f":"Thêm một nguồn <strong>Webcam</strong>, kéo nó vào một góc của khung vẽ và đổi kích thước bằng các tay nắm của nó.","manual.264150f36676":"Thêm một lớp phủ <strong>Ảnh</strong> hoặc <strong>Trình duyệt</strong> lên trên. Thứ tự trong danh sách là thứ tự trên khung vẽ: mục trên cùng của danh sách nằm ở phía trước.","manual.a329c46899d6":"Tạo thêm cảnh trong dock <strong>Cảnh</strong> — ví dụ “Sắp bắt đầu”, “Chơi game” và “Quay lại ngay” — và chuyển qua lại giữa chúng.","manual.9c8d5730d1bb":"<strong>Mẹo:</strong> Chỉ cần thay đổi thuộc tính của một nguồn dùng chung một lần, nó sẽ thay đổi trong mọi cảnh đang dùng nguồn đó.","manual.fd869e76d280":"<strong>Bản xem trước:</strong> trên Windows, macOS và Linux với X11, bản xem trước chương trình được vẽ thẳng từ card đồ họa, nên việc kéo, co giãn và xoay đều có cảm giác tức thì. Trên Wayland, một bản xem trước tiêu chuẩn được dùng, với cùng khả năng chỉnh sửa trên khung vẽ.","manual.87eca68fecaa":"Bộ lọc và chuyển cảnh","manual.36a962cf3902":"Xếp chồng bộ lọc trên từng nguồn, ngay trên card đồ họa, và chọn cách một cảnh nhường chỗ cho cảnh tiếp theo.","manual.4708b4dbab34":"Thêm khóa chroma","manual.9df34cebcaf5":"Nhấp chuột phải vào một nguồn — chẳng hạn một camera quay phông xanh — và chọn <strong>Bộ lọc</strong>.","manual.9981601a6174":"Thêm <strong>Khóa Chroma (Chroma Key)</strong> và điều chỉnh <strong>Màu khóa</strong>, <strong>Độ tương đồng</strong>, <strong>Độ mượt</strong> và <strong>Tràn màu (Spill)</strong>: màu được khóa sẽ biến mất trực tiếp trên khung vẽ.","manual.b76bd309a9f6":"Thêm các bộ lọc khác khi bạn cần — <strong>Hiệu chỉnh Màu</strong>, <strong>LUT</strong>, <strong>Làm mờ</strong>, <strong>Mặt nạ</strong>, <strong>Làm nét</strong> — và kéo chúng để sắp xếp lại chuỗi.","manual.db41fe5a40e4":"Đặt hiệu ứng chuyển cảnh","manual.bea9e11be98d":"Trong <strong>Điều khiển</strong>, mở bộ chọn chuyển cảnh, chọn <strong>Cắt</strong>, <strong>Mờ dần</strong>, <strong>Trượt</strong>, <strong>Quét</strong>, <strong>Stinger</strong> hoặc <strong>Luma Wipe</strong>, và đặt thời lượng.","manual.eada58ce5b2e":"Với <strong>Stinger</strong>, hãy chọn media và điểm chuyển cảnh của nó; với <strong>Luma Wipe</strong>, hãy chọn dải chuyển sắc và độ mềm của nó.","manual.79756cb8b209":"Chuyển cảnh để xem hiệu ứng chuyển cảnh phát. Trong Chế độ Studio, hiệu ứng phát khi bạn đưa bản xem trước lên chương trình.","manual.2c0c025b4264":"Bộ ghép hình và hiệu ứng hình ảnh","manual.b768e85eff32":"Nghiêng 3D, keyer đầu ra, đóng băng và nhân bản, một họ hiệu ứng làm mờ, chuyển cảnh chuyển động có quy tắc, studio shader, mặt nạ Bézier và stinger có track matte.","manual.d2b720eca5a5":"Nghiêng 3D và phối cảnh","manual.d665cc2f2296":"Mở <strong>Chỉnh sửa biến đổi</strong> trên một mục và đặt <strong>Nghiêng X</strong>, <strong>Nghiêng Y</strong> cùng cường độ <strong>Phối cảnh</strong> để ghim nguồn trong không gian 3D. Một phép biến đổi không có độ nghiêng sẽ hiển thị đúng như trước.","manual.c4077ba2b72d":"Keyer đầu ra","manual.d4220af54ed9":"Mở <strong>Công cụ → Keyer đầu ra</strong> và thêm bất kỳ nguồn nào làm một lớp phủ lên <strong>Đầu ra chương trình</strong>, nằm trên mọi cảnh và giữ nguyên qua mọi lần chuyển cảnh — logo kênh, huy hiệu LIVE, dòng chữ chân màn hình.","manual.0677e571c1f8":"Sắp xếp lại các lớp và đặt độ mờ đục, vị trí, kích thước và trạng thái bật hay tắt cho từng lớp. Chúng xuất hiện như nhau trong bản xem trước, bản ghi, luồng phát và đa màn hình giám sát.","manual.1e484119e149":"Đóng băng khung hình và nhân bản nguồn","manual.4cdb8e22f58b":"Nhấp chuột phải vào một nguồn, mở <strong>Bộ lọc</strong> và thêm <strong>Đóng băng</strong>: nó giữ khung hình cuối cùng trong chương trình, bản xem trước, bản ghi và luồng phát cùng lúc. Tắt nó đi để bỏ đóng băng.","manual.59fd957b48dc":"Nhấp nút <strong>Nhân bản</strong> (⧉) trên hàng của một nguồn để đặt một nguồn cấp vào nhiều cảnh hoặc nhiều vị trí, mỗi bản nhân có phép biến đổi và bộ lọc riêng.","manual.a90410d6b30c":"Hiệu ứng làm mờ","manual.eeb69e428aa3":"Trong <strong>Bộ lọc</strong> của một nguồn, thêm một trong các kiểu làm mờ bên cạnh Gaussian: <strong>định hướng</strong> (vệt chuyển động theo một góc), <strong>xuyên tâm</strong> (xoáy quanh một tâm), <strong>Thu phóng</strong> (vệt kiểu dolly-zoom) hoặc <strong>Điểm ảnh hóa</strong> (khảm).","manual.54261c9f6b8f":"Chuyển cảnh di chuyển và quy tắc chuyển cảnh","manual.ef17a04962be":"Chọn chuyển cảnh <strong>Di chuyển</strong>: các mục có trong cả hai cảnh sẽ lướt từ vị trí, tỷ lệ, góc xoay và vùng cắt cũ sang cái mới thay vì cắt ngang, còn các mục chỉ có trong một cảnh sẽ hiện dần hoặc mờ dần.","manual.e31792f9e737":"Mở <strong>Công cụ → Quy tắc chuyển cảnh</strong> để gán cho một cặp cảnh hiệu ứng chuyển cảnh và thời lượng riêng. Để một mục có hiệu ứng xuất hiện riêng, hãy đặt hiệu ứng hiện dần <strong>Hé lộ</strong> trong <strong>Chỉnh sửa biến đổi</strong>.","manual.bb4e30a1ea68":"Studio shader WGSL","manual.e475acf03bea":"Thêm một <strong>hiệu ứng WGSL của người dùng</strong> làm bộ lọc và chỉnh sửa nó trực tiếp. Các thanh trượt của nó được tạo từ các chú thích <code>// @param</code>, và một thư viện có sẵn gồm thang xám, đảo màu, đường quét và làm tối viền.","manual.424ca3316822":"<strong>Mẹo:</strong> Shader được biên dịch và kiểm tra ngay khi bạn gõ. Một shader không hợp lệ sẽ bị bỏ qua và nguồn hiển thị không qua bộ lọc — không bao giờ gây sập ứng dụng.","manual.c24e8b5ee2c0":"Mặt nạ Bézier","manual.37870edaacbc":"Thêm bộ lọc <strong>mặt nạ vẽ tự do</strong> và vẽ một đường khép kín: kéo các tay nắm, nhấp đúp để thêm một điểm, nhấp chuột phải để xóa một điểm. Bộ lọc có các hình dạng đặt sẵn, độ mờ biên cho từng cạnh và tùy chọn đảo ngược.","manual.f44ad1306530":"Xuất bất kỳ đường nào thành mẫu <strong>luma-wipe</strong> thang xám để dùng lại hình dạng đó làm hiệu ứng chuyển cảnh.","manual.e4c8b0c52b3e":"Stinger có track matte","manual.b35494db6ce6":"Đặt một stinger mang độ trong suốt của nó dưới dạng <strong>Track matte</strong>, với phần lấp đầy và phần matte <strong>Cạnh nhau</strong> hoặc <strong>Xếp chồng</strong>, để độ trong suốt tồn tại qua các codec vốn làm mất nó (H.264 và HEVC). Tùy chọn <strong>hạ âm thanh chương trình</strong> xuống dưới âm thanh riêng của stinger trong lúc nó phát.","manual.3879f0c73d18":"Lớp phủ và các nguồn khác","manual.cea21c089e39":"Phát lại, danh sách phát, tiêu đề, đồng hồ đo, lớp phủ thống kê, bộ hẹn giờ, lớp phủ đầu vào và hai nguồn cấp qua mạng, tất cả đều từ menu <strong>+ / Thêm nguồn</strong> của dock <strong>Nguồn</strong>.","manual.4a459b922e4b":"Phát lại tức thì","manual.2e042aa67065":"Trước tiên hãy bật bộ đệm phát lại (<strong>Bật phát lại</strong> trong dock <strong>Điều khiển</strong>), rồi chọn <strong>Phát lại tức thì</strong> từ <strong>+ / Thêm nguồn</strong> và đặt nó vào một cảnh.","manual.d7645da473a6":"Đưa những giây gần nhất lên chương trình bằng phím tắt phát lại của bạn — được sao chép mà không mã hóa lại và phát ở tốc độ <strong>100%</strong>, <strong>50%</strong> hoặc <strong>25%</strong>, được làm chậm lại chứ không tự bịa thêm khung hình. Bạn có thể tua hoặc tạm dừng trong khi nó phát.","manual.5b8095e70de0":"Khi kết thúc, nguồn tự xóa, nên chương trình tự quay về trực tiếp.","manual.6433eaab9b10":"<strong>Mẹo:</strong> Phát lại chậm được cố ý để im lặng: âm thanh bị làm chậm sẽ bị nhòe, nên nó được bỏ đi thay vì làm giả.","manual.f0b63d46cd74":"Danh sách phát media và nhạc nền","manual.37ed12f9d130":"Thêm <strong>Danh sách phát media (liền mạch)</strong> và tạo một danh sách có thứ tự với điểm vào, điểm ra và điểm nhắc cho từng mục. Cả danh sách phát qua một bộ giải mã duy nhất, nên các điểm nối chính xác đến từng khung hình và thực sự liền mạch.","manual.ef41fa6ad9b5":"Chọn cách nó chạy — <strong>Lặp</strong>, <strong>Ngẫu nhiên</strong> hoặc <strong>giữ mục cuối</strong> — và chuyển qua từng mục bằng phím tắt tiếp theo và trước đó. Một danh sách phát chỉ có âm thanh sẽ hiện <strong>tên bản nhạc hiện tại</strong> trên khung vẽ và phát qua dải kênh bàn trộn riêng của nó; nhấp nút <strong>Giám sát</strong> của dải kênh đó để nghe.","manual.6e641ae2bd92":"Với nhạc phát mà không hiển thị gì trên màn hình, hãy chọn <strong>+ / Thêm nguồn → Nhạc nền…</strong> và chọn một hoặc nhiều tệp <code>.mp3</code>, <code>.wav</code> hoặc <code>.flac</code>, có thể phát ngẫu nhiên nếu bạn muốn. Nó tắt tiếng âm thanh riêng của video phông nền, nên lúc nào cũng chỉ có một thứ được nghe thấy.","manual.b9aad55133bf":"Trình thiết kế tiêu đề và bảng tỷ số","manual.5382c093aaef":"Thêm <strong>Tiêu đề / Bảng tỷ số</strong> để mở trình thiết kế: xếp chồng các lớp <strong>Văn bản</strong>, <strong>Ảnh</strong> và <strong>Hình dạng</strong>, với chữ có viền và đổ bóng cùng hiệu ứng xuất hiện và biến mất (mờ dần, trượt, quét).","manual.7b8fea70655a":"Gắn các trường với một tệp được theo dõi (một ô CSV hoặc một con trỏ JSON) hoặc với một biến của studio, rồi điều khiển trực tiếp: đổi tên, sửa tỷ số hoặc phát hiệu ứng mà không cần động tới cảnh.","manual.88a9422e37a9":"Trực quan hoá âm thanh","manual.87f4a5bdd624":"Thêm <strong>Trực quan hoá âm thanh</strong> và chọn một kiểu — <strong>Cột phổ</strong>, <strong>Máy hiện sóng</strong> hoặc <strong>Đồng hồ VU</strong> stereo — rồi gắn nó với bất kỳ dải kênh bàn trộn, rãnh nào hoặc bản trộn master. Nó cũng hiển thị cả âm thanh của video phông nền.","manual.0ae90a461adb":"Trong <strong>Thuộc tính</strong> của nguồn, bật <strong>Màu cổ điển</strong> để có các dải xanh lá, vàng và đỏ, hoặc để tắt để dùng một màu đặc duy nhất. Kích thước, số cột và tốc độ rơi cũng nằm ở đó.","manual.0d1ceffb08ba":"<strong>Mẹo:</strong> Bộ trực quan hoá nghe tín hiệu <strong>sau fader</strong>, nên một nguồn bị tắt tiếng sẽ hiển thị phẳng: nó hiển thị đúng những gì bạn nghe thấy.","manual.ec642e1cf0cc":"Lớp phủ thống kê, đồng hồ split và lớp phủ đầu vào","manual.6b4fe6f81cb0":"Thêm <strong>Thống kê hiệu năng (HUD)</strong> để hiển thị các số liệu đo được của dock thống kê trên khung vẽ — số khung hình mỗi giây, CPU, bộ nhớ, thời gian dựng hình trên GPU, khung hình bị rớt và bitrate trực tiếp — mỗi dòng đều bật hoặc tắt được. Mức sử dụng GPU được cố ý bỏ ra, vì nó không được đo.","manual.cbd8a4b88736":"Thêm <strong>Đồng hồ split speedrun</strong>, nhập một tệp LiveSplit <code>.lss</code>, và chạy nó bằng các phím tắt toàn cục cho split, hoàn tác, bỏ qua và đặt lại, so với thành tích tốt nhất cá nhân, các đoạn tốt nhất hoặc mức trung bình. Tệp chỉ được đọc; một lượt chạy không bao giờ được ghi ngược lại.","manual.fbf4bbeaf903":"Thêm <strong>Lớp phủ đầu vào (phím/tay cầm)</strong> để hiển thị bàn phím, chuột và tay cầm trực tiếp, theo một trong bốn bố cục (WASD, bàn phím thu gọn, tay cầm hai cần, cần điều khiển đối kháng 8 hướng). Bàn phím và chuột hoạt động trên Windows; tay cầm hoạt động trên cả ba hệ điều hành.","manual.bf794edb3c25":"Thanh mạng xã hội và kênh","manual.5f898056ef11":"Thêm <strong>Thanh mạng xã hội</strong> từ <strong>+ / Thêm nguồn</strong>: một bảng liệt kê các tài khoản của bạn. Chọn một nền tảng cho từng hàng — <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> dưới dạng huy hiệu có màu, hoặc <strong>Tùy chỉnh</strong> với nhãn và màu của riêng bạn — và nhập tên tài khoản (ví dụ <code>@mychannel</code>). Thêm một dòng tiêu đề tùy chọn (“Theo dõi tôi”), sắp xếp lại các hàng, và đặt cỡ chữ cùng màu sắc.","manual.1dab9389547a":"Mọi trường đều chỉnh sửa được trong <strong>Thuộc tính</strong> của nguồn. Các hàng không có tên tài khoản sẽ bị bỏ qua, nên bạn có thể giữ một danh sách đầy đủ và chỉ điền những gì bạn dùng.","manual.1a4ac3c2e0bf":"Tin nhắn chat nổi bật","manual.c5d58a7d58be":"Mở <strong>Công cụ → Tin nhắn chat nổi bật…</strong> (hoặc bảng lệnh). Hộp thoại liệt kê các dòng mới nhất từ mọi lớp phủ chat đang chạy: nhấp <strong>Ghim</strong> trên một dòng để ghim nó lên chương trình dưới dạng biểu ngữ mà người xem luồng phát và bản ghi đều thấy.","manual.162d364796a2":"Đặt màu <strong>biểu ngữ</strong> và <strong>chữ</strong> trong hộp thoại, và nhấp <strong>Bỏ ghim</strong> để gỡ nó khỏi sóng. Bản thân lượt ghim sẽ tự xóa khi khởi động lại, theo thiết kế: lời nhắc tên của hôm qua không bao giờ ám ảnh chương trình hôm nay.","manual.89a84c53e014":"Làm nổi bật con trỏ và hiệu ứng nhấp chuột","manual.d0a5d9fb047d":"Nhấp chuột phải vào một nguồn chụp Màn hình hoặc Cửa sổ, mở <strong>Bộ lọc</strong> và thêm <strong>Hiệu ứng con trỏ</strong>: <strong>Quầng sáng con trỏ</strong> (màu và bán kính), <strong>Gợn sóng khi bấm</strong> cho chuột trái và phải được mã hóa bằng màu, và <strong>Hiện phím bấm</strong> tùy chọn bên cạnh con trỏ. Thay đổi hiển thị trực tiếp.","manual.4a17c44757e4":"<strong>Lưu ý:</strong> Hiệu ứng con trỏ chỉ hoạt động trên Windows; macOS và Linux tự vẽ con trỏ. Lớp phủ đầu vào và tính năng hiện phím bấm chỉ đọc đầu vào <strong>khi chúng đang bật</strong>, và vẽ thẳng vào hình ảnh: không có gì được lưu trữ hay ghi nhật ký.","manual.8bdb1aadf964":"Nguồn mạng: nhận tín hiệu LAN và Freally Link","manual.797fe86a1fe8":"Thêm <strong>Nhận tín hiệu LAN (trình nghe SRT/RTMP)</strong> để mở một trình nghe trên máy tính này, rồi trỏ ứng dụng camera trên điện thoại, một bộ mã hóa hoặc một máy tính thứ hai tới địa chỉ được hiển thị (kèm mã QR). Tín hiệu xuất hiện trong cảnh với dải kênh bàn trộn riêng. SRT có thể mang một cụm mật khẩu AES tùy chọn; RTMP không có cơ chế xác thực riêng, nên biểu mẫu ưu tiên SRT.","manual.e2761818ccef":"Để chia sẻ giữa hai bản Freally Capture, hãy bật đầu ra <strong>Freally Link</strong> trên máy tính <strong>gửi</strong> và đặt <strong>Khóa ghép nối</strong> của nó — không thể bật đầu ra này nếu không có khóa. Trên máy tính <strong>nhận</strong>, thêm <strong>Freally Link (phiên bản khác)</strong>, nhấp <strong>Quét mạng LAN</strong> và nhập khóa: chương trình của bên gửi sẽ xuất hiện dưới dạng một nguồn. Không bên nào cần ffmpeg, và một bên nhận không có khóa sẽ không bao giờ thấy được một khung hình nào.","manual.a793cb271e32":"<strong>Lưu ý:</strong> Cả hai nguồn mạng đều <strong>tắt cho đến khi bạn thêm chúng</strong>, chỉ ở trong mạng của riêng bạn, và không bao giờ chạm tới internet: không có gì tìm thấy bạn, và không có gì gọi ra ngoài.","manual.de10be5dcf2c":"Đồng hồ đếm ngược Sắp bắt đầu","manual.71b47ef78ea4":"Một màn hình chờ trước chương trình chỉ với một cú nhấp: một đồng hồ đếm ngược lớn tới giờ phát sóng, trên nền ảnh, GIF, video, dải chuyển sắc hoặc nhạc, nhấp nháy khi về 0 và chờ bạn chuyển sang chương trình.","manual.303493002776":"Thêm đồng hồ đếm ngược","manual.f78f2994b5d5":"Trong dock <strong>Nguồn</strong>, mở <strong>+ / Thêm nguồn</strong> và chọn <strong>Sắp bắt đầu…</strong>. Nó đặt một đồng hồ đếm ngược toàn khung vẽ — một dòng chú thích phía trên một con số lớn — vào cảnh.","manual.c4bff5a4f06e":"Nhập <strong>chú thích</strong> (“Sắp bắt đầu”, “Quay lại ngay”), rồi đặt thời gian bằng <strong>bộ chọn giờ</strong>: <strong>giờ</strong> (1–12), <strong>phút</strong> theo bước năm phút, và <strong>AM</strong> hoặc <strong>PM</strong>. Nguồn sẽ đếm ngược tới thời điểm đó trong ngày.","manual.59b00df516f1":"Khi về 0, đồng hồ đếm ngược <strong>nhấp nháy và dừng ở 0:00:00</strong> — nó không bao giờ tự chuyển cảnh. Hãy chuyển sang cảnh trực tiếp của bạn khi bạn đã sẵn sàng. Mọi trường đều chỉnh sửa được trong <strong>Thuộc tính</strong> của nguồn.","manual.1dfb2d817d39":"Chọn phông nền","manual.edc2450aeecd":"Chọn kiểu nền: <strong>Chuyển sắc</strong> hai màu (mặc định), một màu <strong>Đặc</strong>, một <strong>Ảnh</strong> (nhấp <strong>Duyệt…</strong>), hoặc <strong>Trong suốt</strong> để một nguồn bên dưới hiện qua.","manual.07a5fd9ac032":"Chọn một tệp <strong>GIF</strong> hoặc <strong>video</strong> và nó sẽ lặp phía sau các con số, <strong>được co giãn cho vừa và căn giữa</strong>, nên toàn bộ hình ảnh đều hiện ra và không có gì bị cắt.","manual.1cda5be75376":"Thêm <strong>Nhạc nền</strong> bằng nút <strong>Duyệt…</strong> của hộp thoại (MP3, WAV, FLAC, M4A, AAC, OGG hoặc Opus). Nhạc phát lặp, bạn nghe được trong bản xem trước, và nó là một phần của bản ghi và luồng phát. Âm thanh riêng của video phông nền bị tắt tiếng, nên lúc nào cũng chỉ có một thứ được nghe thấy.","manual.b39b6b7add20":"<strong>Mẹo:</strong> Để có nhạc phía sau một màn hình trơn, hãy để phông nền ở Chuyển sắc hoặc Trong suốt và thêm nhạc: một đồng hồ đếm ngược gọn gàng có nhạc nền.","manual.84f506f4fca5":"Bàn trộn âm thanh","manual.480e299c8728":"Trộn mọi nguồn âm thanh, gửi chúng tới tối đa 6 rãnh, và làm sạch micrô của bạn — tất cả đều trực tiếp.","manual.bcbc220b3e63":"Mỗi nguồn âm thanh là một dải kênh trong <strong>Bàn trộn</strong>: tên, đồng hồ đo mức, fader, tắt tiếng, giám sát, bộ lọc và các chấm rãnh (1–6).","manual.03b920dc5376":"Kéo fader để đặt mức âm lượng, nhấp <strong>Tắt tiếng</strong> hoặc <strong>Giám sát</strong>, và gửi nguồn tới bất kỳ rãnh nào trong 6 rãnh.","manual.9a9991c7dc36":"Mở <strong>bộ lọc</strong> của một nguồn và thêm <strong>Khử ồn</strong> (xử lý tín hiệu cổ điển, không AI), <strong>Cổng Nhiễu (Noise Gate)</strong>, <strong>Bộ nén (Compressor)</strong>, <strong>Bộ giới hạn (Limiter)</strong>, <strong>EQ</strong> hoặc <strong>Khuếch đại</strong>.","manual.1a58b91bc5aa":"Gán phím tắt <strong>Nhấn để nói</strong> hoặc <strong>Nhấn để tắt tiếng</strong>, và theo dõi đồng hồ <strong>LUFS</strong> để biết độ lớn âm thanh của chương trình.","manual.7158a36ed4d5":"<strong>Lưu ý cho macOS:</strong> macOS không tự cung cấp “những gì bạn nghe thấy” cho ứng dụng. Hãy dùng âm thanh ScreenCaptureKit (macOS 13 trở lên) ở nơi có sẵn, hoặc cài một thiết bị ảo như BlackHole và chọn nó làm nguồn âm thanh hệ thống. Freally Capture sẽ hướng dẫn bạn, và vẫn tiếp tục ghi ngay cả khi một nguồn không thể mở.","manual.bfdd510698ef":"Ghi hình","manual.e39b756fce99":"Ghi chương trình trên nhiều rãnh bằng bộ mã hóa phần cứng của card đồ họa, hoặc ghi không mất dữ liệu theo định dạng riêng của Capture.","manual.ad438c2dbf4b":"Trong <strong>Cài đặt → Đầu ra</strong>, chọn một bộ mã hóa. Freally Capture tìm <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> hoặc <strong>VideoToolbox</strong> và chọn cái tốt nhất; <strong>x264</strong> chạy trên bộ xử lý luôn có sẵn làm phương án dự phòng.","manual.3bc1870f8449":"Chọn một vùng chứa — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> hoặc <strong>WebM</strong> — hoặc định dạng không mất dữ liệu riêng của Capture là <strong>freally-video</strong> (<code>.frec</code>), vốn không cần cài thêm gì khác.","manual.e2a332927058":"Gửi các nguồn tới các rãnh âm thanh (tối đa 6) để micrô, âm thanh hệ thống và khách mời của bạn được tách riêng khi biên tập. Tùy chọn bật <strong>chia tệp</strong> và <strong>một bản sao cục bộ theo rãnh riêng khi đang phát</strong>.","manual.e0fa2f5a9430":"Nhấp <strong>Bắt đầu ghi</strong> trong <strong>Điều khiển</strong>. Một chấm <strong>REC</strong> màu xanh lá hiển thị thời gian và số rãnh. Nhấp <strong>Dừng</strong> để hoàn tất tệp.","manual.b1eb969490f1":"<strong>Lưu ý về codec:</strong> MP4 với H.264 và AAC (cũng như HEVC hoặc AV1) dùng các codec được bảo hộ bằng sáng chế, do <strong>ffmpeg</strong> cung cấp, vốn <em>không được đóng gói kèm</em>: Freally Capture tải nó về vào lần đầu tiên bạn cần và kiểm tra nó. Định dạng không mất dữ liệu <strong>freally-video</strong> không cần tải gì về.","manual.691bff5377a8":"Ghi hình và phát lại chuyên sâu","manual.3c2d08430816":"Mọi thứ xoay quanh tệp ghi: bản ghi riêng cho từng nguồn, công cụ cắt đoạn, độ trong suốt thực sự, chia tệp và đánh dấu theo sự kiện, các tác vụ sau khi ghi, kiểm tra tính toàn vẹn và mã thời gian SMPTE. Tất cả đều tắt cho đến khi bạn bật lên, và không thứ nào kết nối internet.","manual.537ffa2b9063":"Ghi ISO theo từng nguồn","manual.e57aa725fa41":"Mở <strong>Cài đặt → Đầu ra</strong> và tìm <strong>Ghi ISO</strong>. Bật <strong>Ghi “{name}” thành tệp ISO riêng</strong> cho từng nguồn bạn muốn có bản sạch: mỗi nguồn được ghi trước khi ghép hình, ở kích thước và tốc độ khung hình của khung vẽ, nên mọi tệp đều khớp với chương trình trên dòng thời gian biên tập. Mỗi khách mời từ xa là một nguồn, nên mỗi khách cũng có một tệp riêng.","manual.4bce8f25ec9c":"Giữ <strong>Ghi kèm bộ lọc của nguồn</strong> được chọn để có hình ảnh đã xử lý, hoặc bỏ chọn để lấy nguồn thô, và chọn <strong>Định dạng ISO</strong> cùng <strong>Bộ mã hóa video ISO</strong> cho từng bản ghi. Âm thanh được lấy sau bộ lọc nhưng trước fader và tắt tiếng, nên một quyết định khi trộn không bao giờ làm im lặng một tệp ISO.","manual.7f29ae4e2c55":"<strong>Mẹo:</strong> Hai bản ghi ISO chạy thoải mái trên một card đồ họa tầm trung; mỗi bản thêm vào sẽ tốn thêm một lượt kết xuất và mã hóa, và bảng cài đặt nói rõ điều đó.","manual.b2aad668b8b9":"Công cụ cắt đoạn phát lại và clip","manual.c8af16e1cd4f":"Mở một bản ghi đã lưu trong cửa sổ <strong>Cắt</strong> từ danh sách bản ghi, xem từng khung hình bằng <strong>Lùi một khung hình</strong> và <strong>Tiến một khung hình</strong>, và đặt các điểm bằng <strong>Điểm vào</strong> và <strong>Điểm ra</strong> trong khi xem.","manual.1f80dfd03a36":"Hãy kiểm tra huy hiệu trước khi xuất. Huy hiệu xanh lá <em>“Xuất mà không mã hóa lại”</em> nghĩa là điểm vào nằm trên một khung hình khóa (gần như tức thì và không mất dữ liệu); huy hiệu màu hổ phách cảnh báo rằng tệp sẽ được mã hóa lại — nhấn <strong>Khung hình khóa</strong> để bắt điểm vào cho một đoạn cắt không mất dữ liệu. Nhấp <strong>Xuất đoạn cắt</strong>, hoặc <strong>9:16</strong> để xuất một phiên bản dọc.","manual.8a92b0b480f4":"Ghi hình có độ trong suốt","manual.79bfd450e6aa":"Trong <strong>Cài đặt → Đầu ra</strong>, bật <strong>Ghi với độ trong suốt (alpha)</strong> để ghi chương trình trên nền trong suốt sang định dạng <code>.frec</code> của Capture. Bản ghi có lượt kết xuất trong suốt riêng, nên bản xem trước và luồng phát của bạn vẫn giữ hình ảnh bình thường. Từ danh sách bản ghi, hãy xuất một tệp <code>.mov</code> <strong>ProRes 4444</strong> hoặc <strong>QuickTime Animation (QTRLE)</strong> cho phần mềm biên tập của bạn; MP4 và MKV sẽ làm phẳng độ trong suốt.","manual.fade0a9d0454":"<strong>Lưu ý:</strong> Độ trong suốt chỉ là một cờ trong phần đầu tệp <code>.frec</code>, nên các tệp này phát được ở mọi nơi <code>.frec</code> phát được, và các tệp cũ hơn sẽ mở ra dưới dạng không trong suốt.","manual.33e5c9a96c5d":"Chia tệp và đánh dấu tự động","manual.5596d47693a3":"Trong cài đặt chia tệp cho <code>.frec</code>, chọn bắt đầu một tệp mới khi <strong>chuyển cảnh</strong>, khi <strong>đánh dấu</strong> hoặc ở mỗi <strong>bước kịch bản</strong>. Mỗi phần bắt đầu đúng ở khung hình của sự kiện đó, và một phần kéo dài ít nhất một giây, nên một loạt sự kiện dồn dập không thể tạo ra hàng đống tệp nhỏ xíu.","manual.7fc20a49c196":"Bật <strong>Tự động đặt dấu chương khi có sự kiện của studio</strong> để đánh dấu các lần chuyển cảnh, lần lưu phát lại, lần kết nối lại, các đợt rớt khung hình, cảnh báo và thao tác của quy tắc thành chương. Chúng được đưa vào tiêu đề chương MKV và tệp <code>.chapters.txt</code> bên cạnh bản ghi, cùng với các dấu bạn đặt bằng phím tắt.","manual.519fceb746f3":"Sau khi ghi: chuỗi xử lý và kiểm tra tính toàn vẹn","manual.561bb55d7a18":"Tạo một <strong>Chuỗi xử lý sau ghi hình</strong> cho từng hồ sơ từ một tập bước cố định — <strong>Kiểm tra</strong>, <strong>Remux sang MP4</strong>, <strong>Chuẩn hóa âm lượng</strong>, <strong>Đổi tên</strong>, <strong>Chuyển vào thư mục</strong>, <strong>Sao chép vào thư mục</strong>, <strong>Hiện trong trình quản lý tệp</strong> và <strong>Báo cho script Lua</strong>. Chuỗi chạy nền với hàng đợi trực tiếp và dừng ở lỗi đầu tiên. Cố ý không có bước “chạy lệnh bất kỳ”.","manual.2f93cddd1f21":"Chạy kiểm tra tính toàn vẹn sau một bản ghi hoặc bất cứ lúc nào bạn muốn, để nhận kết quả rõ ràng là ổn, cảnh báo hay thất bại cho <strong>Vùng chứa</strong>, <strong>Tính liên tục video</strong>, <strong>Tính liên tục âm thanh</strong>, <strong>Xen kẽ âm thanh và video</strong> và <strong>Thời lượng</strong>. Tệp <code>.frec</code> được kiểm tra chuyên sâu; các tệp khác được kiểm tra cấu trúc và giải mã qua ffmpeg.","manual.0d291aee5546":"Xuất một bản sao để chia sẻ khi bạn dừng ghi","manual.124d2a00ed27":"Trong <strong>Cài đặt → Đầu ra</strong>, với vùng chứa đặt là <code>.frec</code>, đánh dấu <strong>Cũng lưu một MP4 chia sẻ được cạnh bản gốc</strong>. Khi một bản ghi kết thúc, một lượt xuất chạy nền sẽ ghi một tệp <code>.mp4</code> mà ai cũng phát được, đặt bên cạnh bản gốc không mất dữ liệu.","manual.a37303723389":"Bản sao xuất hiện trong hàng đợi sau ghi hình, được đặt tên sao cho không bao giờ ghi đè lên thứ gì, và không bao giờ động tới bản gốc. Tính năng này tắt cho đến khi bạn bật lên.","manual.7ed8656eb1ff":"Mã thời gian SMPTE LTC","manual.3d97874c3064":"Mở <strong>Mã thời gian SMPTE (LTC)</strong>, bật <strong>Tạo LTC lên một track</strong>, và chọn rãnh bàn trộn cùng tốc độ khung hình để cấp cho máy ghi và camera bên ngoài. Đặt <strong>Đọc LTC từ</strong> thành một đầu vào âm thanh để hiển thị một dòng mã thời gian trên lớp phủ thống kê và đóng dấu các dấu chương LTC. Mã thời gian âm thanh cổ điển, hoàn toàn ngoại tuyến, chính xác tới một khung hình ở 24, 25 và 30 fps.","manual.a9f690169703":"Phát trực tiếp","manual.8f6df4580812":"Phát thẳng từ máy tính của bạn tới một nền tảng qua RTMP hoặc RTMPS — không bao giờ qua một máy chủ nào của chúng tôi.","manual.dba22b61cdcc":"Mở <strong>Cài đặt → Phát</strong> và nhấp <strong>Thêm đích</strong>. Chọn <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> hoặc <strong>RTMP tùy chỉnh</strong>.","manual.2192731aac47":"Dán <strong>khóa phát</strong> của bạn — được giữ trên máy tính của bạn và hiển thị dưới dạng đã che — rồi đặt bitrate và bộ mã hóa cho dịch vụ đó.","manual.040014e94f16":"Nhấp <strong>Phát trực tiếp</strong> trong <strong>Điều khiển</strong>. Đèn <strong>Trực tiếp</strong> bật sáng, và dock thống kê hiển thị bitrate, số khung hình bị rớt và tình trạng của luồng phát.","manual.0cd441959cb4":"Nếu kết nối bị rớt, Freally Capture <strong>tự kết nối lại</strong>, và bản ghi cục bộ của bạn vẫn tiếp tục chạy bất kể luồng phát ra sao. Đặt <strong>độ trễ luồng phát</strong> nếu bạn muốn.","manual.dc8ebcea4893":"Nhấp <strong>Kết thúc phát</strong> để dừng.","manual.973adc03e43c":"An toàn phát sóng","manual.53fa9293a65e":"Không để mất chương trình — trước, trong và sau khi phát.","manual.de8792b14216":"Trước: kiểm tra trước khi lên sóng","manual.ed9a4b7bfaf5":"Nhấp <strong>Phát trực tiếp</strong> sẽ chạy một danh sách kiểm tra trước: các đích phát đã có khóa, tìm thấy bộ mã hóa dùng được, mọi nguồn đều ổn định và còn đủ dung lượng đĩa cho bản ghi — mỗi mục xanh hoặc đỏ, kèm cách sửa chỉ một cú nhấp — cùng các lời nhắc về mức micrô và âm thanh máy tính và về bộ đệm phát lại, những lời nhắc không bao giờ chặn một chương trình chỉ có màn hình. Một tùy chọn cài đặt có thể <strong>giữ nút Phát trực tiếp cho đến khi mọi bước kiểm tra chặn đều xanh</strong>; nếu không, vẫn có nút “Vẫn phát trực tiếp”.","manual.9b63c5c64ba1":"Trong khi phát: cảnh báo, tình trạng và chuyển dự phòng","manual.9c386b745073":"<strong>Cảnh báo an toàn</strong> theo dõi trong khi bạn đang phát trực tiếp hoặc đang ghi: âm thanh chương trình im lặng, vỡ tiếng kéo dài, hình đen hoặc đứng hình, và <em>dự báo</em> sắp hết dung lượng đĩa (“còn khoảng 22 phút ở bitrate hiện tại”). Chúng xuất hiện dưới dạng một biểu ngữ bạn có thể đóng, và trình đọc màn hình sẽ thông báo chúng — không bao giờ là một hộp thoại làm gián đoạn chương trình.","manual.b7c8c66a5330":"<strong>Bảng tình trạng nguồn</strong> (bảng lệnh → “Tình trạng nguồn…”) liệt kê trạng thái, tốc độ khung hình, tuổi của khung hình cuối, số khung hình bị rớt và số lần khởi động lại của mọi nguồn, với nút <strong>Khởi động lại</strong> và <strong>Thuộc tính</strong> cho từng nguồn.","manual.92bd60ef963b":"Nếu bộ mã hóa phần cứng gặp lỗi giữa lúc phát hoặc ghi — driver bị đặt lại, card đồ họa quá tải — <strong>chuyển bộ mã hóa dự phòng</strong> sẽ chuyển sang một bộ mã hóa phần cứng khác hoặc sang x264. Luồng phát kết nối lại và tiếp tục chạy, bản ghi tiếp tục trong một tệp mới, và một thông báo cho biết chính xác chuyện gì đã xảy ra. Sự cố mạng không bao giờ gây ra việc chuyển đổi.","manual.50a02fe4fe7b":"<strong>Nút khẩn cấp</strong> (một phím tắt toàn cục do bạn chọn) chuyển chương trình — cùng khung vẽ dọc và mọi máy chiếu — sang một màn hình riêng tư, dừng mọi nguồn ghi hình và tắt tiếng toàn bộ âm thanh, kể cả micrô, trong khi luồng phát và bản ghi vẫn giữ kết nối. Việc quay lại cần một bước xác nhận hai bước có chủ đích. Đặt màu hoặc ảnh cho màn hình riêng tư bên cạnh phím tắt trong <strong>Cài đặt → Phím tắt</strong>.","manual.a73a2857361e":"Sau khi phát: bản ghi an toàn và thoát có thứ tự","manual.bf07b060e7e7":"Bản ghi MP4 và MOV được ghi theo <strong>phân mảnh</strong>, nên một sự cố hay mất điện vẫn để lại một tệp phát được (MKV và <code>.frec</code> vốn đã như vậy). Nếu một phiên kết thúc giữa lúc đang ghi, lần khởi động sau sẽ đề nghị <strong>Sửa chữa</strong> chỉ bằng một cú nhấp thành một bản sao <code>(repaired)</code>; tệp gốc không bao giờ bị động tới.","manual.da5eeb31c1b8":"Thoát khi đang phát trực tiếp, đang ghi hoặc đã bật phát lại sẽ cho bạn thấy những gì sẽ xảy ra, rồi tắt <strong>theo thứ tự</strong>: kết thúc luồng phát, hoàn tất bản ghi, lưu bộ đệm phát lại, lưu công việc của bạn.","manual.26b3f2c32e05":"<strong>Tên tệp bản ghi</strong> theo một mẫu (<strong>Cài đặt → Đầu ra</strong>) được tạo từ các token — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — cho bản ghi, phát lại và ảnh tĩnh, với thư mục riêng cho phát lại và ảnh tĩnh.","manual.27c3f23547ac":"<strong>Xuất chẩn đoán</strong> lưu một gói thông tin kỹ thuật vào một tệp trên máy tính của bạn, được tạo theo một danh sách cho phép nghiêm ngặt để khóa phát, mật khẩu, đường dẫn tệp và tên không bao giờ có trong đó. Bạn có thể đọc nội dung của nó trước; nó nằm ở nơi bạn lưu và không bao giờ được gửi đi đâu cả.","manual.5199babf9b90":"Nguồn và thiết bị","manual.306121fdda68":"Mọi thứ nằm giữa ống kính và khung vẽ: tín hiệu thử, hiệu chỉnh đồng bộ, chữ lấy từ tệp, bộ hẹn giờ, bản đồ phím tắt, bàn trộn chuyên sâu và điều khiển thiết bị thực thụ.","manual.5eacf1ee941f":"Tín hiệu thử và hiệu chỉnh đồng bộ hình-tiếng","manual.920b7abd63cc":"Thêm một nguồn <strong>Tín hiệu thử</strong> (<strong>Nguồn → + → Tín hiệu thử</strong>): thanh màu, lưới hiệu chỉnh, dải quét chuyển động, âm chuẩn 1 kHz ở −20 dBFS, hoặc mẫu kết hợp <strong>chớp sáng và tiếng bíp</strong> để đồng bộ hình-tiếng — hình và tiếng được tạo từ một đồng hồ duy nhất. Kiểm tra máy chiếu, bộ mã hóa hoặc đích phát mà không cần cắm camera.","manual.788073298328":"Mở bàn làm việc <strong>Hiệu chỉnh đồng bộ hình-tiếng</strong> (bảng lệnh → “Hiệu chỉnh đồng bộ hình-tiếng…”). Chọn camera và micrô cần căn khớp, hướng camera vào chương trình đang chớp sáng (hộp thoại có thể mở một máy chiếu toàn màn hình cho việc này), và để nó đo trong khoảng mười hai giây. Công cụ tìm chớp sáng và tiếng bíp qua nhiều chu kỳ và đề nghị áp dụng độ lệch đo được cho micrô; thanh trượt thủ công vẫn được giữ làm phương án dự phòng. Phép đo chạy qua màn hình và loa của bạn, nên độ trễ nhỏ của chính chúng cũng nằm trong kết quả — và nếu thất bại, công cụ sẽ cho biết <em>vì sao</em>.","manual.825c83c405fb":"Bộ hẹn giờ, đồng hồ và chữ lấy từ tệp","manual.85622b429b51":"Một nguồn <strong>Hẹn giờ</strong> hiển thị đồng hồ (với định dạng của riêng bạn và một độ lệch UTC cố định tùy chọn), <strong>Đếm ngược</strong> (theo một khoảng thời lượng, hoặc tới mốc giờ kế tiếp trong ngày — khi về 0, nó có thể nhấp nháy hoặc chuyển cảnh), <strong>Bấm giờ</strong>, hoặc <strong>thời gian kể từ khi bạn lên sóng hoặc bắt đầu ghi</strong>. Bắt đầu, tạm dừng và đặt lại nó từ <strong>Thuộc tính</strong> của nguồn, hoặc gán hai phím tắt toàn cục điều khiển <em>tất cả</em> bộ hẹn giờ cùng lúc (<strong>Cài đặt → Phím tắt</strong>).","manual.fcd4f802968f":"Một nguồn <strong>Văn bản</strong> có thể <strong>đọc từ một tệp được theo dõi</strong> (<strong>Thuộc tính → Đọc từ tệp</strong>): toàn bộ tệp <code>.txt</code>, một ô CSV (theo tên hoặc số thứ tự cột), hoặc một giá trị JSON (một con trỏ như <code>/teams/0/score</code>). Thay đổi hiển thị trong vòng nửa giây. Bảng tỷ số và dòng chữ chân màn hình mà không cần dịch vụ nào phía sau.","manual.1d106549f0ce":"Bản đồ phím tắt và bàn trộn","manual.5d6ad89f147c":"<strong>Bản đồ phím tắt</strong> (bảng lệnh → “Bản đồ phím tắt…”) liệt kê <em>mọi</em> cách gán phím — thao tác toàn cục cùng nhấn để nói và nhấn để tắt tiếng của từng nguồn — tìm kiếm và lọc được, và gắn cờ xung đột một cách trung thực: cùng một tổ hợp được viết theo hai cách sẽ hiện là dùng chung, và một phím mà hệ thống từ chối (vì một ứng dụng khác đang sở hữu) sẽ được báo rõ. <strong>Xuất bảng ghi nhớ</strong> ghi một tài liệu tham khảo Markdown vào thư mục Downloads của bạn.","manual.e32e382b9753":"Mỗi dải kênh bàn trộn có <strong>cân bằng trái phải</strong> (cân bằng stereo; ở giữa là hoàn toàn không cân bằng, và nhấp đúp sẽ đặt lại), <strong>solo PFL</strong> (bản giám sát chỉ nghe các dải kênh đang solo; bản trộn chương trình không bao giờ thay đổi) và <strong>trộn xuống mono</strong>. Cân bằng và mono nằm trong menu “⋯” của dải kênh; solo nằm ngay trên dải kênh.","manual.5dbd70dfc92d":"Thiết bị chuyên sâu: khử xen kẽ và điều khiển camera","manual.f8e60899a881":"<strong>Thuộc tính</strong> của một thiết bị ghi video cung cấp <strong>Khử xen kẽ</strong> cho các nguồn cấp xen kẽ, chẳng hạn card ghi hình nhận tín hiệu từ camera và máy chơi game đời cũ: bỏ trường, bob, tuyến tính, hòa trộn hoặc thích ứng chuyển động, kèm thứ tự trường. Tính năng chạy giống nhau trên mọi hệ điều hành; đổi chế độ sẽ khởi động lại thiết bị.","manual.34192e6d30fd":"<strong>Điều khiển camera</strong> — phơi sáng, cân bằng trắng, lấy nét, thu phóng, khuếch đại và nhiều hơn nữa — xuất hiện trong cùng mục <strong>Thuộc tính</strong> khi camera đang chạy. Windows và Linux dùng các điều khiển UVC tiêu chuẩn; macOS hiển thị bất cứ thứ gì hệ thống báo về, thường là không có gì, và bảng điều khiển nói rõ điều đó thay vì hiện những thanh trượt không làm gì cả. Mọi điều chỉnh đều được lưu trong một <strong>hồ sơ cho camera đó</strong>, được áp dụng lại khi camera được cắm lại hoặc ứng dụng khởi động lại; <strong>Đặt lại hồ sơ</strong> khôi phục giá trị mặc định.","manual.f77f10d8c967":"Tự động hóa và điều khiển","manual.726216fb4de1":"Để studio tự vận hành bằng quy tắc, macro và bộ điều khiển phần cứng — tất cả đều bị giới hạn trong một danh sách lệnh studio cố định duy nhất, nên không tự động hóa nào có thể chỉ định một tệp, khởi chạy một chương trình hay kết nối internet.","manual.193521bd4921":"Quy tắc, macro và biến","manual.e8ee7ccab125":"Mở <strong>Công cụ → Quy tắc tự động hoá &amp; macro…</strong> và thêm một quy tắc. Chọn một trong chín trình kích hoạt (chuyển cảnh, luồng phát bắt đầu hoặc dừng, bản ghi bắt đầu hoặc dừng, lỗi nguồn, mức âm thanh vượt một ngưỡng, hệ thống rảnh, một cửa sổ được focus, một thời điểm trong ngày, hoặc một tệp được theo dõi thay đổi), thêm điều kiện (giá trị của một biến, đang phát, đang ghi), và chọn một thao tác studio. Mọi quy tắc đều bắt đầu ở trạng thái <strong>tắt</strong>: hãy bật nó lên để kích hoạt.","manual.5deaa7ba718f":"Tạo một macro dưới dạng danh sách bước có tên — chạy một thao tác, chờ, đặt một biến — với số lần lặp và một phím tắt toàn cục tùy chọn. Chạy nó từ ứng dụng, một phím tắt, một quy tắc hoặc API điều khiển từ xa.","manual.30ee5b1326f2":"Đặt một <strong>biến</strong> của studio trong một macro và dùng nó dưới dạng <code>{{name}}</code> bên trong bất kỳ nguồn Văn bản nào: chữ thay đổi ngay khi macro đặt giá trị.","manual.5eb10fc04538":"Bộ điều khiển: MIDI, OSC và bảng cảm ứng","manual.ba0c838f1688":"Mở <strong>Công cụ → Điều khiển MIDI…</strong> và dạy nó một phím, núm xoay hay fader cho một thao tác, một macro, một lần chuyển cảnh, một fader bàn trộn hoặc một nút tắt tiếng — với đèn và fader có motor phản ánh trạng thái thật của studio. Không cổng MIDI nào được mở cho đến khi bạn chọn một cổng.","manual.cc993cb0d974":"Bật <strong>Nghe OSC</strong> để cho phép các bộ điều khiển kiểu TouchOSC và bàn điều khiển ánh sáng gửi các địa chỉ như <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> và <code>/mixer/vol</code>. Tính năng này tắt theo mặc định và chỉ lắng nghe trên máy tính này trừ khi bạn cho phép mạng của mình. OSC không có mật khẩu riêng.","manual.134e5f4269f9":"Mở <strong>Công cụ → Bảng LAN &amp; tally…</strong> để cung cấp một trang điều khiển — nút cảnh với tally trực tiếp, fader bàn trộn và phím thao tác — cho bất kỳ điện thoại nào qua mã QR. Mọi yêu cầu đều cần mật khẩu, và nó chỉ lắng nghe trên máy tính này trừ khi bạn cho phép mạng của mình. Trang tally hiển thị toàn màn hình màu đỏ hoặc xanh lá; thêm <code>?scene=NAME</code> để theo dõi một cảnh.","manual.fc4cd96b860d":"Tổ hợp phím và lớp phím tắt","manual.ec4a9a334753":"Trong một ô phím tắt, gán một tổ hợp phím đơn giản (Ctrl+Shift+M) hoặc một tổ hợp hai bước (Ctrl+K, rồi 3) — phím thứ hai chỉ bị chiếm khi tổ hợp đang chờ. Gán cho một phím tắt một <strong>Lớp</strong> để nó chỉ hoạt động khi lớp đó đang bật; các lớp giữ nguyên trạng thái cho đến khi bạn đổi.","manual.70ad05980925":"Camera và kịch bản chương trình","manual.24b33b058b99":"Mở <strong>Công cụ → Máy quay PTZ…</strong>, thêm một camera theo địa chỉ VISCA-over-IP của nó, lưu các vị trí đặt sẵn có tên cho quay ngang, nghiêng và thu phóng, và liên kết một vị trí đặt sẵn với một cảnh để khi chuyển sang cảnh đó sẽ gọi lại góc máy. PTZ chỉ ở trong mạng của bạn, và một camera chỉ tồn tại vì bạn đã nhập địa chỉ của nó: không có gì được tự dò tìm.","manual.c9d86b995c5a":"Mở <strong>Công cụ → Hiện kịch bản chương trình…</strong> và liệt kê các bước — một cảnh, thời gian nó được giữ, và các thao tác tùy chọn — chuyển bước thủ công hoặc tự động, với dòng “tiếp theo” trực tiếp và thời gian còn lại. Kịch bản chuyển cảnh theo cách thông thường, có thể hoàn tác, và không bao giờ sửa bộ sưu tập cảnh của bạn.","manual.5c94bed2d737":"<strong>Lưu ý:</strong> Mọi quy tắc, macro, cách gán MIDI hoặc OSC, nút bảng điều khiển và bước kịch bản đều đi qua cùng một danh sách lệnh cố định với API điều khiển từ xa, nên không bộ điều khiển nào làm được điều mà chính các nút của ứng dụng không làm được. Mọi cổng lắng nghe mạng đều tắt theo mặc định và chỉ ở trên máy tính này trừ khi bạn cho phép mạng của mình, và phần cài đặt OSC và bảng điều khiển sẽ cảnh báo bạn rằng lưu lượng mạng không được mã hóa trước khi cổng được mở.","manual.1f3fd1c7ddc9":"Phát đa luồng","manual.dcac0a03a29b":"Phát tới nhiều nền tảng cùng lúc — thẳng từ máy tính của bạn, không có dịch vụ chuyển tiếp nào ở giữa.","manual.42d9628818da":"Thêm hai đích phát trở lên trong <strong>Cài đặt → Phát</strong> và bật từng đích.","manual.4144fe0d9694":"Đặt cài đặt bộ mã hóa riêng cho một nền tảng nếu nền tảng đó cần bitrate khác.","manual.cb21d6bb96be":"Nhấp <strong>Phát trực tiếp</strong>: bạn phát tới mọi đích đang bật cùng một lúc. Dock thống kê hiển thị tình trạng và bitrate của từng đích, và một đích gặp lỗi không bao giờ kéo các đích khác sập theo.","manual.aba9a5f55973":"Tùy chọn ghi một bản sao cục bộ theo rãnh riêng cùng lúc, và lưu phát lại bằng phím tắt phát lại trong khi bạn đang phát.","manual.af9343c245a7":"<strong>Hiện miễn phí:</strong> mọi tính năng — phát đa luồng, SRT và WHIP, mọi bộ lọc, script, phát lại, các gói chuyển cảnh và API điều khiển từ xa — hiện đều miễn phí cho tất cả mọi người. Các phiên bản sau này có thể được bán.","manual.c08320c45003":"Độ tin cậy và thấu hiểu buổi phát","manual.532ab322d03c":"Diễn tập, đo lường và lý giải chương trình của bạn. Mọi thứ ở đây đều tắt hoặc trung tính theo mặc định, và không thứ nào kết nối internet.","manual.80390ae1a9d7":"Trình mô phỏng mạng","manual.7e620ced841e":"Trong <strong>Cài đặt → Phát</strong>, mở <strong>Trình mô phỏng mạng (diễn tập)</strong> và chọn một <strong>Hồ sơ</strong> — <strong>Wi-Fi khách sạn</strong>, <strong>Điểm phát di động</strong>, hoặc <strong>Tùy chỉnh</strong> với <strong>Băng thông</strong>, <strong>Độ trễ</strong>, <strong>Độ dao động trễ (jitter)</strong> và các khoảng <strong>Mất kết nối</strong> theo lịch của riêng bạn. Nó chỉ ảnh hưởng đến đầu ra cục bộ của một buổi diễn tập, nên bạn có thể luyện tập kết nối lại, phát đa luồng và lựa chọn bitrate; nó không bao giờ làm chậm một buổi phát thật.","manual.b22d8c51e0bd":"Chế độ diễn tập","manual.083772633b86":"Nhấn nút <strong>Diễn tập</strong> màu tím để chạy toàn bộ chuỗi xử lý — bộ ghép hình, bộ mã hóa, bộ ghép kênh và logic kết nối lại thật — vào một điểm nhận thay thế cục bộ, <strong>không có gì rời khỏi máy tính</strong>. Một huy hiệu <strong>DIỄN TẬP</strong> đánh dấu mọi điều khiển trực tiếp, và khóa phát của bạn thậm chí không bao giờ được đọc, nên bạn có thể diễn tập trước cả khi có khóa. Bạn cũng có thể ghi lại buổi diễn tập.","manual.184d64047c4c":"<strong>Mẹo:</strong> Kết hợp một buổi diễn tập với trình mô phỏng mạng để luyện tập kết nối lại qua một đường truyền yếu, chập chờn từ lâu trước ngày phát.","manual.d2381a584d24":"Dòng thời gian khung hình bị rớt","manual.a6a72c5410a8":"<strong>Dòng thời gian phiên</strong> ghi lại toàn bộ phiên — thời gian kết xuất, hàng đợi bộ mã hóa, bitrate và số khung hình bị rớt của từng đích, các lần kết nối lại, chuyển cảnh, đánh dấu và cảnh báo — trên một biểu đồ thu phóng được. Trong khi dock thống kê cho thấy <em>hiện tại</em>, dòng thời gian trả lời câu hỏi “chuyện gì đã xảy ra ở phút 43?” sau đó.","manual.6e9fee1e85fa":"Báo cáo phiên và benchmark bộ mã hóa","manual.9dd812cbf648":"Bật <strong>Ghi báo cáo phiên (HTML + Markdown) cạnh bản ghi</strong> trong <strong>Cài đặt → Phát</strong> để có bản tóm tắt cục bộ khi phiên kết thúc: thời gian hoạt động, bitrate trung bình và đỉnh của từng đích, thời gian bị gián đoạn, các lần kết nối lại, đánh dấu, cảnh báo và vị trí của bản ghi. Báo cáo ở lại trên máy tính của bạn và tắt theo mặc định.","manual.a9e574b7bd8d":"Dùng <strong>Chạy benchmark bộ mã hóa…</strong> để đo các lượt mã hóa ngắn với mọi bộ mã hóa, cấu hình sẵn và độ phân giải mà máy tính của bạn có — khoảng một phút, hoàn toàn ngoại tuyến — rồi <strong>Áp dụng vào cài đặt ghi hình</strong> từ kết quả. Các lỗi được liệt kê, không bị giấu đi, và benchmark từ chối chạy khi bạn đang phát trực tiếp hoặc đang ghi.","manual.fae310275ed2":"Nguồn chỉ hiện trong luồng phát, hoặc chỉ hiện trong bản ghi","manual.191da176dd0d":"Trên hàng của một nguồn, dùng <strong>Hiện trên stream</strong> / <strong>Ẩn trên stream</strong> và <strong>Hiện trong bản ghi</strong> / <strong>Ẩn trong bản ghi</strong> để giữ thông báo và chat trên luồng phát trực tiếp trong khi bản ghi vẫn sạch, từ cùng một khung vẽ. Nút hình con mắt chính vẫn điều khiển mọi thứ, còn bản xem trước, máy chiếu và đa màn hình giám sát luôn hiển thị toàn bộ chương trình.","manual.46bad2cb618f":"Camera ảo","manual.69ebe5277092":"Dùng chương trình của bạn làm webcam trong bất kỳ ứng dụng gọi video nào. <strong>Chỉ có trên Windows trong 1.2.1.</strong>","manual.ba2b6aa952f7":"Nhấp <strong>Bắt đầu camera ảo</strong> trong <strong>Điều khiển</strong>. Freally Capture thêm một camera hệ thống tên là <strong>“Freally Capture Virtual Camera”</strong>.","manual.cb3cb4585f19":"Trong Zoom, Meet, Discord hoặc Teams, chọn camera đó trong cài đặt video: chương trình của bạn trở thành webcam.","manual.83db59f4a370":"Nhấp <strong>Dừng camera ảo</strong> để gỡ nó.","manual.91c51d55639b":"<strong>Theo từng hệ điều hành:</strong> trên <strong>Windows</strong>, camera được đăng ký cho người dùng của bạn, không cần quyền quản trị, và được gỡ khi bạn dừng nó. Camera <strong>chưa được ký mã</strong>, nên Windows có thể cảnh báo về nó và một ứng dụng gọi video được gia cố bảo mật có thể từ chối nó; một bài thử đầy đủ trong một cuộc gọi thật vẫn chưa được thực hiện. Camera trên <strong>macOS</strong> và <strong>Linux</strong> là các thành phần riêng <em>không có trong bản phát hành này</em>. Freally Capture không bao giờ cài một thành phần hệ thống mà không hỏi, trên bất kỳ hệ điều hành nào.","manual.98839b8e6880":"Nguồn trình duyệt","manual.3ba821584b20":"Đưa thẳng một trang web trực tiếp — lớp phủ thông báo, bảng tỷ số, tiện ích chat — vào một cảnh.","manual.895f07f428cd":"Trong <strong>Nguồn</strong>, nhấp <strong>+</strong> và chọn <strong>Trình duyệt</strong>.","manual.868ee19e975e":"Dán một địa chỉ <strong>http://</strong> hoặc <strong>https://</strong> và đặt kích thước cùng tốc độ khung hình để kết xuất nó.","manual.292e94b0a782":"Ở lần đầu tiên, Freally Capture đề nghị cài thành phần <strong>Môi trường chạy trình duyệt</strong>. Thành phần này được tải về khi bạn yêu cầu và được kiểm tra theo mã hash của nó — không bao giờ được đóng gói kèm ứng dụng — và bạn có thể gỡ nó lại từ <strong>Công cụ → Thành phần</strong>.","manual.cd6d7fbd46ee":"<strong>Chỉ http và https được tải.</strong> Quy tắc này áp dụng cho mọi lần chuyển trang, không chỉ địa chỉ bạn nhập: nếu một trang cố chuyển tới <code>file://</code>, <code>javascript:</code> hoặc <code>data:</code> — qua chuyển hướng, script, cửa sổ bật lên hay khung — việc chuyển sẽ bị <strong>hủy</strong>, nên một trang không thể đọc các tệp của bạn. Trên Windows, trang chạy trong hộp cát của Chromium. Môi trường chạy <strong>chưa được ký mã</strong>. Âm thanh của trang chưa được ghi: phiên bản này chỉ có hình ảnh.","manual.9c0c8f127dd9":"Ghi trò chơi","manual.2c08692420b8":"Ghi một trò chơi toàn màn hình độc quyền mà tính năng ghi cửa sổ thông thường không thấy được. <strong>Chỉ có trên Windows.</strong>","manual.9d162e3861e9":"Trong <strong>Nguồn</strong>, nhấp <strong>+</strong> và chọn <strong>Chụp Trò chơi</strong>. <strong>Hãy đọc thông báo trước</strong>: nó giải thích rủi ro bằng lời lẽ dễ hiểu.","manual.4264b41a7732":"Chấp nhận rủi ro <em>cho riêng trò chơi đó</em>, rồi chọn trò chơi đang chạy từ danh sách.","manual.ab3e826e90f1":"Freally Capture nạp một hook nhỏ vào trò chơi đó và lấy khung hình của nó ở đúng tốc độ khung hình của chính trò chơi.","manual.082fd06e18f9":"<strong>Hãy đọc phần này trước khi dùng.</strong> Ghi trò chơi hoạt động bằng cách <strong>nạp một DLL vào trò chơi</strong>. Phần mềm chống gian lận và phần mềm diệt virus có thể coi đó là hành vi can thiệp, và nó có thể khiến một tài khoản bị <strong>cấm</strong>. Không có gì được nạp tự động: bạn đồng ý <strong>cho từng trò chơi một</strong>, và sự đồng ý đó không bao giờ được dùng cho trò chơi khác — và nó không bao giờ đi kèm trong một bộ sưu tập cảnh được chia sẻ. Nếu một trò chơi từ chối hook, Freally Capture sẽ chuyển về <strong>Chụp Cửa sổ</strong> thông thường kèm một thông báo thay vì thất bại. Các trò chơi HDR và trò chơi Direct3D 12 cũng dùng Chụp Cửa sổ. Trên macOS và Linux, nguồn này không được cung cấp.","manual.43fae75af922":"Bộ đệm phát lại","manual.40bc664c1c0b":"Giữ những khoảnh khắc gần nhất trong bộ nhớ, để một phím tắt lưu lại những gì vừa xảy ra.","manual.7a69241c10c2":"Nhấp <strong>Bắt đầu bộ đệm phát lại</strong> trong <strong>Điều khiển</strong>. Freally Capture giữ những giây gần nhất trong một bộ đệm có kích thước cố định.","manual.684aecea2ba0":"Gán một phím tắt toàn cục <strong>Lưu phát lại</strong> trong <strong>Cài đặt</strong>.","manual.66c44777e965":"Nhấn nó để lưu những giây gần nhất vào một tệp — mà không làm gián đoạn luồng phát hay bản ghi chính của bạn. Một thông báo “Đã lưu phát lại” xác nhận điều đó.","manual.4b598d5daf11":"Máy nhắc chữ","manual.b7fc474ded62":"Một kịch bản cuộn mượt cho người đứng trước camera — trên một bảng trong ứng dụng, một máy chiếu toàn màn hình có thể lật gương, và bảng cảm ứng LAN, tất cả cùng lúc.","manual.f1c548f77750":"Mở máy nhắc chữ từ <strong>Công cụ</strong>, nhập hoặc dán kịch bản của bạn, rồi đặt tốc độ và phông chữ. Điều chỉnh nhịp theo <strong>ký tự mỗi giây</strong>, hoặc chuyển sang <strong>BPM</strong> (50–250 nhịp mỗi phút) để đọc lời bài hát khớp với nhạc; thay đổi nào cũng điều chỉnh lại nhịp của lượt cuộn đang chạy.","manual.3a86eb91938d":"<strong>Thẻ tạm dừng:</strong> gõ <code> -- </code> để có một nhịp ngừng hoặc <code> --N </code> để dừng N giây và nó sẽ trở thành một thẻ duy nhất — con trỏ nhảy qua nó, một lần nhấn Delete hoặc Backspace sẽ xóa nó, và sao chép, dán vẫn giữ nguyên nó.","manual.dc7539148aed":"<strong>Bắt đầu đếm ngược:</strong> bật một đoạn dẫn 3-2-1 tùy chọn, hiển thị trên cả bản xem trước của người vận hành và máy chiếu, để người đọc có một nhịp chuẩn bị trước khi chữ chạy.","manual.f5113c573ac4":"<strong>Mở máy chiếu</strong> cho người đọc (chế độ gương lật hình cho kính chia chùm tia). Mở máy chiếu sẽ đóng cửa sổ của người vận hành, nên bạn có thể điều khiển luồng phát từ cửa sổ chính trong khi họ đọc; khi đã bật đếm ngược, máy chiếu quay lại đầu, đếm ngược rồi phát. Phát, tạm dừng, dừng, tua lại, tua nhanh và bắt đầu lại từ các nút trên màn hình, một phím tắt, MIDI, OSC hoặc bảng LAN — mọi điều khiển luôn đồng bộ với nhau.","manual.5298a60b0152":"<strong>Đọc to</strong> cho nghe thử kịch bản bằng giọng nói của chính hệ thống: các giọng tích hợp sẵn của Windows, của macOS, và trên Linux là <code>spd-say</code> hoặc <code>espeak-ng</code> nếu đã được cài. Không có bộ máy giọng nói nào được đóng gói kèm.","manual.5de1b5efa245":"<strong>Tự động hoàn thành</strong> gợi ý từ và cụm từ bằng màu xám nhạt khi bạn gõ; nhấn Tab để chấp nhận. Mỗi ngôn ngữ trong số 18 ngôn ngữ có từ điển riêng trên máy tính của bạn, chỉ được tải cho ngôn ngữ bạn đang viết.","manual.7fb5d22a1670":"Điều khiển từ xa","manual.b2ba73efdcec":"Điều khiển studio từ một Stream Deck hoặc một bộ điều khiển kiểu Companion — tắt theo mặc định, bảo vệ bằng mật khẩu, trên chính máy tính của bạn.","manual.6396674fcd28":"Mở <strong>Cài đặt → Điều khiển từ xa</strong>, bật <strong>API WebSocket</strong> (tắt theo mặc định), và đặt <strong>Mật khẩu</strong>.","manual.56e0d6d295bb":"Nó lắng nghe trên <code>127.0.0.1</code> — chỉ máy tính này — trừ khi bạn cho phép mạng của mình một cách tường minh.","manual.344e52e3eba1":"Trỏ một client Companion hoặc Stream Deck tới địa chỉ được hiển thị. Chuyển cảnh, chạy hiệu ứng chuyển cảnh, tắt và bật tiếng, bắt đầu và dừng ghi, và lưu phát lại từ các nút phần cứng.","manual.6664edd9ad4c":"Khách mời từ xa và sản xuất chương trình","manual.75ce17238f9b":"Biến một phiên khách mời từ xa thành một chương trình được sản xuất bài bản: tối đa tám khách mời, vẽ trên chương trình trực tiếp, phòng chờ, tín hiệu nhắc riêng, kết nối của từng khách trong nháy mắt, và lưới tự động. Mọi thứ ở đây đều tắt hoặc chưa được gán theo mặc định, và không có gì kết nối cho đến khi bạn mời ai đó.","manual.02d9e34002c8":"Phiên nhiều khách mời","manual.5a6c2ec7640d":"Bắt đầu một phiên khách mời từ xa và chia sẻ liên kết mời hoặc mã QR của nó: <strong>bạn cùng tối đa tám khách mời</strong>, một bộ sưu tập từ một đến chín ô. Mỗi khách là một ô với các điều khiển tắt tiếng riêng, chất lượng kết nối, kênh nhắc và nút đưa lên sóng chỉ bằng một cú nhấp.","manual.34a323a45540":"Khách mời mở liên kết trong trình duyệt web — không cần cài đặt gì — và chạm <strong>Tham gia</strong> để gửi camera và micrô của họ. Một khách mời có Freally Capture có thể mở cùng lời mời đó trong ứng dụng. Lời mời hết hạn sau khoảng thời gian bạn chọn.","manual.4e31042e4a6f":"<strong>Lưu ý:</strong> Hình ảnh và âm thanh đi trực tiếp giữa bạn và từng khách mời, ngang hàng và được mã hóa khi truyền; chỉ bước bắt tay kết nối đi qua một dịch vụ báo hiệu công cộng. Các phiên được thử nghiệm với bốn khách mời; nhiều hơn thì phụ thuộc vào băng thông và bộ xử lý của bạn.","manual.33ff43cd0616":"Telestrator: vẽ trên chương trình trực tiếp","manual.d29f651d6eb9":"Mở <strong>Telestrator</strong> và chọn một công cụ — <strong>Bút</strong>, <strong>Bút dạ quang</strong>, <strong>Mũi tên</strong> hoặc <strong>Hình elip</strong> — rồi vẽ thẳng lên chương trình. Nét vẽ của bạn trở thành một phần của hình ảnh ngay khi bạn vẽ, nên chúng xuất hiện trong bản ghi và luồng phát, chứ không chỉ trong bản xem trước của bạn.","manual.9aa7fc0273fb":"Để nét vẽ <strong>Mờ dần</strong> sau một lúc, hoặc chuyển sang <strong>Chế độ bảng trắng</strong> để <strong>Giữ</strong> chúng cho đến khi bạn xóa. Nét vẽ theo lực nhấn của bút trên bảng vẽ, và <strong>Xóa nét vẽ</strong> có thể được gán cho một phím tắt (chưa được gán theo mặc định).","manual.fc81cd8d37ae":"Phòng chờ","manual.c87beb96ec64":"Bật <strong>Phòng chờ</strong> và khách mời mới sẽ chờ ngoài sóng trong khi bạn kiểm tra camera và micrô của họ trong <strong>Xem trước phòng chờ</strong>. Khi họ đã sẵn sàng, nhấp <strong>Cho lên sóng</strong>. Khách mời sẽ thấy biểu ngữ “bạn đang ở phòng chờ”, trong ứng dụng hoặc trên trang web.","manual.1d47c8224f50":"Nhắc và trò chuyện","manual.569d461035c1":"Gửi cho một khách mời một lời <strong>Nhắc</strong> riêng — với các mẫu đặt sẵn như <strong>30 giây</strong>, <strong>Kết thúc đi</strong>, <strong>Sắp đến lượt bạn</strong> và <strong>Nói to hơn</strong> — qua kênh ngang hàng sẵn có của phiên. Khách mời thấy lời nhắc kèm đồng hồ đếm ngược trực tiếp, không bao giờ xuất hiện trong chương trình.","manual.c66c9d5359bf":"Bảng chất lượng kết nối","manual.4541cc1ee0f5":"Theo dõi trực tiếp kết nối của từng khách mời — thời gian khứ hồi, tỷ lệ mất gói, độ phân giải và tốc độ khung hình bạn nhận được, và độ dao động trễ — với huy hiệu xanh lá, hổ phách hoặc đỏ và một biểu đồ lịch sử nhỏ, để một kết nối đang yếu đi lộ ra trước khi người xem của bạn nhận thấy.","manual.bf8e764221e5":"Lưới khách mời tự động","manual.ffe3c227cdfc":"Bật <strong>Lưới tự động</strong> để giữ các khách mời đang lên sóng trong một lưới gọn gàng từ một đến chín ô, tự sắp xếp lại khi khách tham gia, rời đi hoặc được đưa lên sóng, hoặc nhấn nút sắp xếp để làm ngay. Mỗi vị trí công bố tên của khách mời dưới dạng biến <code>{{guestN}}</code>, nên một nguồn tiêu đề trở thành bảng tên tự cập nhật.","manual.e8630fabd4e5":"Quản lý studio và quy trình làm việc","manual.c8c487196725":"Làm cho cả một bố cục trở nên di động và chia sẻ được, giữ các phiên bản có tên của cảnh, tùy biến giao diện ứng dụng, và đặt các thao tác yêu thích chỉ cách một lần chạm — tất cả trên máy tính của bạn, không cần máy chủ.","manual.f87995a7cf6c":"Gói cảnh và phiên bản","manual.074bb2bf9453":"Mở hộp thoại không gian làm việc từ <strong>Bộ sưu tập cảnh → Quản lý bộ sưu tập cảnh…</strong>: các công cụ gói, so sánh, ảnh chụp nhanh, sao lưu và bố cục dock đều ở đó.","manual.8dce3a052a05":"Nhấp <strong>Xuất gói…</strong> để đóng gói bộ sưu tập hiện tại cùng các tệp của nó (ảnh, media, LUT, mặt nạ, phông chữ) thành một tệp <code>.fcappack</code> di động. Địa chỉ web và đường dẫn mạng được liệt kê là <em>bên ngoài</em> thay vì được đóng gói, và phông chữ được gắn cờ về giấy phép.","manual.c1bba88df9c5":"Nhấp <strong>Nhập gói…</strong> và chọn một tệp <code>.fcappack</code>: nó được thêm vào dưới dạng một bộ sưu tập mới, tìm các tệp của nó trên máy tính này, và chuyển sang bộ sưu tập đó.","manual.69e7b9f6e8ab":"Nhấp <strong>So sánh &amp; hợp nhất…</strong> để so sánh bộ sưu tập hiện tại với một bộ sưu tập khác, một gói hoặc một ảnh chụp nhanh. Xem lại các cảnh, nguồn, phép biến đổi, bộ lọc và trạng thái hiển thị được thêm, bị xóa hoặc thay đổi, rồi chọn chính xác những thay đổi cần đưa vào. Chọn một cảnh sẽ mang theo các nguồn mà cảnh đó dùng.","manual.862a75c84629":"Nhấp <strong>Ảnh chụp nhanh…</strong>, đặt tên cho một điểm kiểm tra và chọn <strong>Lưu ảnh chụp nhanh</strong>. <strong>Khôi phục</strong> đưa nó trở lại sau này — bố cục hiện tại của bạn được lưu thành một ảnh chụp nhanh trước, nên việc khôi phục không bao giờ là một chiều. Tối đa 50 ảnh chụp nhanh được giữ lại, kèm dung lượng đĩa chúng chiếm.","manual.8058b1480d14":"<strong>Mẹo:</strong> Ảnh chụp nhanh là lịch sử có tên, bên cạnh tự động lưu và hoàn tác. Hãy tạo một ảnh trước khi thực hiện một thay đổi rủi ro, và bạn luôn có một mốc có nhãn để quay lại.","manual.1d55a62a5fdf":"Sao lưu, khôi phục và chế độ di động","manual.250b89a976de":"Trong hộp thoại không gian làm việc, nhấp <strong>Sao lưu và khôi phục…</strong>, rồi <strong>Xuất bản sao lưu…</strong> để lưu mọi thứ — cài đặt, hồ sơ và bộ sưu tập cảnh — trong một tệp <code>.fcapbackup</code> duy nhất.","manual.560e7e269f11":"Trên một máy tính mới, nhấp <strong>Khôi phục từ bản sao lưu…</strong>, đánh dấu những gì cần đưa vào (<strong>Cài đặt</strong>, <strong>Bộ sưu tập cảnh</strong>, <strong>Hồ sơ</strong>) và chọn <strong>Khôi phục mục đã chọn</strong>. Sau đó khởi động lại Freally Capture để tải các bộ sưu tập và hồ sơ đã khôi phục.","manual.5b26da4b8793":"Để chạy từ một ổ USB, hãy đặt một tệp tên là <code>freally-portable.txt</code> bên cạnh chương trình: khi đó toàn bộ dữ liệu của nó nằm trong thư mục của chương trình thay vì trong hồ sơ người dùng của bạn. <strong>Cài đặt → Giới thiệu</strong> cho biết chế độ di động có đang bật không và dữ liệu nằm ở đâu.","manual.a31a49d41d7d":"<strong>Lưu ý:</strong> Khóa phát và mật khẩu không bao giờ được ghi vào bản sao lưu — hãy nhập lại chúng sau khi khôi phục.","manual.5b446c4ea972":"Giao diện, bố cục và thao tác nhanh","manual.8eea476bde73":"Mở <strong>Cài đặt → Giao diện</strong> và chọn giao diện <strong>Tùy chỉnh</strong> để chỉnh sửa bảng màu, với <strong>cảnh báo độ tương phản</strong> trực tiếp, rồi dùng <strong>Xuất .fctheme…</strong> hoặc <strong>Nhập .fctheme…</strong> để chia sẻ nó.","manual.7cc0bc3a4e74":"Trong <strong>Bố cục dock</strong> của hộp thoại không gian làm việc, lưu cách sắp xếp hiện tại dưới một cái tên và nhấp vào một bố cục đã lưu để chuyển sang nó.","manual.c9044c09b979":"Trong <strong>Cài đặt</strong>, gõ vào <strong>Tìm cài đặt…</strong> để nhảy tới bất kỳ cài đặt nào; một dấu hiệu cho biết bạn đã thay đổi những mục nào kể từ khi mở hộp thoại.","manual.a4640858ad4d":"Chọn <strong>Công cụ → Thao tác nhanh…</strong> để mở lưới nút. Nhấp <strong>Chỉnh sửa</strong>, rồi <strong>Thêm nút</strong>, đặt nhãn và màu cho từng nút, và thêm <strong>trang</strong>. Một nút có thể chuyển cảnh, chạy macro, phát một ô của bảng âm thanh hoặc chạy một lệnh studio.","manual.74ff6472576d":"<strong>Mẹo:</strong> Các nút thao tác nhanh chạy cùng các lệnh studio như phím tắt, và lưới nút được dùng chung với bảng cảm ứng LAN: thiết lập một lần là nó cũng có trên điện thoại của bạn.","manual.74a883a037bc":"Cài đặt","manual.5feaf4600834":"Hồ sơ, bộ sưu tập cảnh, phím tắt và ngôn ngữ. Mọi thứ hiện đều miễn phí, nên không có gì cần kích hoạt. <strong>Cài đặt</strong> là một cửa sổ duy nhất với các mục — Chung, Giao diện, Phát, Đầu ra, Phát lại, Phím tắt, Mạng, Trợ năng và Giới thiệu — được mở từ <strong>thanh menu</strong> (Tệp, Chỉnh sửa, Xem, Dock, Hồ sơ, Bộ sưu tập cảnh, Công cụ và Trợ giúp).","manual.9f6a04e85e39":"<strong>Áp dụng nghĩa là áp dụng.</strong> Cửa sổ Cài đặt chỉnh sửa một bản sao: không có gì thay đổi cho đến khi bạn nhấp <strong>Áp dụng</strong> hoặc <strong>OK</strong>, và <strong>Hủy</strong> khôi phục chính xác những gì bạn đã có, kể cả bản xem trước giao diện.","manual.3fc0968ef6f9":"<strong>Hồ sơ và bộ sưu tập cảnh:</strong> giữ các thiết lập riêng biệt — chẳng hạn “Phát trực tiếp” và “Ghi cục bộ” — và chuyển qua lại giữa chúng mà không cần khởi động lại, từ menu <strong>Hồ sơ</strong> và <strong>Bộ sưu tập cảnh</strong>.","manual.ce6f52861bdb":"<strong>Phím tắt:</strong> gán mọi thao tác từ một danh sách không thể xung đột — chọn một phím tắt cho một thao tác và nó sẽ biến mất khỏi danh sách của mọi thao tác khác, nên hai tính năng không bao giờ dùng chung một phím. <strong>Không</strong> sẽ giải phóng phím đó trở lại.","manual.be52349f05be":"<strong>Trợ năng:</strong> chọn màu đồng hồ đo của bàn trộn, bao gồm một bộ màu an toàn cho người mù màu. Toàn bộ ứng dụng hoạt động được bằng bàn phím, và trình đọc màn hình sẽ thông báo khi lên sóng, ghi hình, kết nối lại và khi rớt khung hình.","manual.a79c94673558":"<strong>Ngôn ngữ:</strong> chọn một trong 18 ngôn ngữ; ứng dụng thay đổi ngay lập tức, và tiếng Ả Rập hiển thị từ phải sang trái.","manual.59274c49ac87":"Báo cáo sự cố","manual.c02ed8aec89d":"Bạn quyết định một sự cố có được gửi tới nhà phát triển hay không, và bạn thấy chính xác những gì sẽ được gửi.","manual.4ed327c34aeb":"Khi ứng dụng hiển thị một lỗi do chính nó gây ra, một nút <strong>Báo cáo</strong> xuất hiện bên cạnh.","manual.95da4b53fdcc":"Sau một lần sập, lần khởi động tiếp theo sẽ đề nghị <strong>Báo cáo</strong> hoặc <strong>Bỏ qua</strong>.","manual.6207904599f4":"<strong>Báo cáo</strong> mở trang báo cáo của Freally Capture trên trang web này trong trình duyệt của bạn, với các thông tin kỹ thuật đã được điền sẵn: bạn có thể đọc nhưng không thể thay đổi chúng. Hãy thêm những gì bạn đang làm và, nếu muốn, một địa chỉ email. Không có gì được gửi đi trừ khi bạn nhấn <strong>Gửi</strong> ở đó.","manual.6acd4e789ccd":"Không có gì được gửi ngầm, và <strong>Bỏ qua</strong> hoàn toàn không gửi gì cả.","manual.69bd78234ffb":"Quyền riêng tư và mạng","manual.42f9b04c2640":"Freally Capture không có tài khoản, không thu thập dữ liệu sử dụng, và không có dịch vụ đám mây nào của chúng tôi. Dưới đây là chính xác những gì kết nối internet và những gì không.","manual.81fe73d241a8":"<strong>Không tài khoản, không thu thập dữ liệu sử dụng.</strong> Ứng dụng không bao giờ yêu cầu bạn đăng nhập và không bao giờ gửi cảnh, bản ghi hay bất kỳ dữ liệu sử dụng nào của bạn đi đâu cả.","manual.3735a28566e9":"<strong>Luồng phát của bạn đi thẳng tới nền tảng.</strong> Nó truyền từ máy tính của bạn tới các dịch vụ bạn thiết lập — không có máy chủ chuyển tiếp nào của chúng tôi.","manual.512b8fa00684":"<strong>Bản ghi của bạn ở lại trên máy tính của bạn,</strong> trong thư mục bạn chọn. Không có gì được tải lên.","manual.c299fcfa1fde":"<strong>Khóa phát của bạn ở lại trên máy tính của bạn,</strong> được hiển thị dưới dạng đã che và chỉ được gửi tới dịch vụ mà bạn phát tới.","manual.414a08bd0219":"<strong>Khách mời từ xa kết nối ngang hàng.</strong> Chỉ bước bắt tay của phiên đi qua một dịch vụ báo hiệu công cộng, và chỉ khi bạn bắt đầu một phiên.","manual.20c95c4687b3":"<strong>Lớp phủ chat đọc phần chat công khai</strong> từ kênh mà bạn trỏ tới, giống như một người xem chưa đăng nhập — không cần tài khoản, khóa hay đăng nhập.","manual.efe87d55bed1":"<strong>Hai thành phần chỉ được tải về khi bạn cần đến chúng lần đầu:</strong> ffmpeg, cho các codec mà các nền tảng yêu cầu, và môi trường chạy trình duyệt, cho nguồn trình duyệt. Mỗi thành phần đến từ chính nhà phát hành của nó và được kiểm tra trước khi dùng.","manual.3601a272b3b0":"<strong>Việc kiểm tra cập nhật</strong> tải một tệp nhỏ mỗi lần khởi chạy, và khi bạn chọn <strong>Kiểm tra cập nhật…</strong>. Không có thông tin nào về bạn hay máy tính của bạn được gửi kèm, và không có gì được cài đặt trừ khi bạn đồng ý.","manual.11abc96d8e21":"<strong>Báo cáo sự cố chỉ được gửi khi bạn nhấn Gửi</strong> trên trang báo cáo, sau khi bạn đã đọc nội dung của nó (xem <a href=\"#report\">Báo cáo sự cố</a>).","manual.804fa6536d40":"<strong>Không AI.</strong> Mọi bộ lọc — khử nhiễu, khóa chroma, ánh xạ tông màu — đều là xử lý tín hiệu cổ điển. Ứng dụng không chứa mô hình học máy nào và không tải về mô hình nào."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
